use std::{hint::black_box,time::Instant};
fn median(mut values:Vec<f64>)->f64 {values.sort_by(f64::total_cmp);values[values.len()/2]}
fn main(){
println!("count,columns,append_256_summary_us,reduce_us,output_points");
for count in [10000,100000,1000000] {
let mut h=History::new(count);let mut input=Vec::with_capacity(count);let mut out=Vec::with_capacity(count);h.generate(count,&mut input);
let mut update=Vec::new();let mut reduce=Vec::new();let mut lengths=Vec::new();
for i in 0..34 {
let start=Instant::now();h.generate(256,&mut input);let u=start.elapsed().as_secs_f64()*1e6;
let start=Instant::now();h.reduce(0..h.len,1920,&mut out);let r=start.elapsed().as_secs_f64()*1e6;
black_box(&out);if i>=4 {update.push(u);reduce.push(r);lengths.push(out.len()as f64);}
}
println!("{count},1920,{:.3},{:.3},{}",median(update),median(reduce),median(lengths)as usize);
}
}

