#[test]
fn summary_and_reduction_match_original_after_ring_wrap() {
    let mut rng=0x56789341u64;
    let mut rand=||{rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;rng as usize};
    for capacity in [257,513,10000,100000,1000000] {
        let mut history=History::new(capacity);
        let mut scratch=Vec::with_capacity(capacity);
        let mut reduced=Vec::with_capacity(capacity);
        history.generate(capacity,&mut scratch);
        for round in 0..5 {
            history.generate(256,&mut scratch);
            for _ in 0..40 {
                let start=rand()%capacity;
                let end=start+1+rand()%(capacity-start);
                let summary=history.query(start,end);
                let direct=(start..end).fold(Summary::default(),|s,i|{
                    let p=(history.head+i)%capacity;
                    history.combine(s,history.scan(p..p+1))
                });
                assert_eq!((summary.first,summary.last,summary.min,summary.max,summary.gap),
                           (direct.first,direct.last,direct.min,direct.max,direct.gap),"{capacity} round {round}");
                let columns=193.min(end-start);
                history.reduce(start..end,columns,&mut reduced);
                let mut expected=Vec::new();
                for col in 0..columns {
                    let a=start+col*(end-start)/columns;
                    let b=start+(col+1)*(end-start)/columns;
                    let s=history.query(a,b);
                    if s.gap {expected.extend((a..b).map(|i|history.at(i)));}
                    else {
                        let mut indices=[s.first,s.min,s.max,s.last];
                        indices.sort_unstable_by_key(|i|(*i+capacity-history.head)%capacity);
                        let mut last=NONE;
                        for i in indices { if i!=last {expected.push(history.data[i]);last=i;} }
                    }
                }
                assert_eq!(bytemuck::cast_slice::<Point2D,u8>(&reduced),bytemuck::cast_slice::<Point2D,u8>(&expected));
                // All retained nongap samples remain chronological.
                let xs:Vec<_>=reduced.iter().filter_map(|p|p.position().map(|p|p[0])).collect();
                assert!(xs.windows(2).all(|p|p[0]<p[1]));
                assert_eq!(reduced.iter().filter(|p|p.position().is_none()).count(),(start..end).filter(|&i|history.at(i).position().is_none()).count());
            }
        }
    }
}
#[test]
fn no_reduction_returns_identical_data_and_empty_ranges_stay_empty() {
    let mut h=History::new(10000);let mut scratch=Vec::new();h.generate(10711,&mut scratch);
    let mut reduced=Vec::new();h.reduce(17..9981,20000,&mut reduced);
    let expected:Vec<_>=(17..9981).map(|i|h.at(i)).collect();
    assert_eq!(bytemuck::cast_slice::<Point2D,u8>(&reduced),bytemuck::cast_slice::<Point2D,u8>(&expected));
    h.reduce(100..100,10,&mut reduced);assert!(reduced.is_empty());
}
